import { expect, it } from "vitest";

import { renderDevVars } from "./render-dev-vars.ts";

it("writes the values sorted and quoted under the header naming the config", () => {
  expect(renderDevVars({ A: "1", B: "2" }, "apps/web/api/cloudflare.config.ts")).toBe(
    '# Generated by infra gen from apps/web/api/cloudflare.config.ts\nA="1"\nB="2"\n',
  );
});

it("answers undefined with no values, and fails a value .dev.vars cannot hold", () => {
  expect(renderDevVars({}, "x")).toBeUndefined();
  expect(() => renderDevVars({ KEY: 'a"b' }, "x")).toThrow("x: KEY's value has a quote, backslash or newline");
});
